 INSERT INTO subscriber_reporting_daily(day,channel,joined,left_count) SELECT strftime('%Y-%m-%d','now'),COALESCE(OLD.chat_kind,OLD.channel),0,1 WHERE OLD.state IN ('pending','active') AND OLD.destination NOT LIKE 'deleted:%' AND OLD.chat_kind IS NULL AND OLD.sms_kind=0 AND (NEW.state NOT IN ('pending','active') OR NEW.destination LIKE 'deleted:%' OR COALESCE(NEW.chat_kind,NEW.channel) <> COALESCE(OLD.chat_kind,OLD.channel)) ON CONFLICT(day,channel) DO UPDATE SET joined=joined+excluded.joined,left_count=left_count+excluded.left_count;
 INSERT INTO subscriber_reporting_daily(day,channel,joined,left_count) SELECT strftime('%Y-%m-%d','now'),COALESCE(NEW.chat_kind,NEW.channel),1,0 WHERE NEW.state IN ('pending','active') AND NEW.destination NOT LIKE 'deleted:%' AND NEW.chat_kind IS NULL AND NEW.sms_kind=0 AND (OLD.state NOT IN ('pending','active') OR OLD.destination LIKE 'deleted:%' OR COALESCE(OLD.chat_kind,OLD.channel) <> COALESCE(NEW.chat_kind,NEW.channel)) ON CONFLICT(day,channel) DO UPDATE SET joined=joined+excluded.joined,left_count=left_count+excluded.left_count;
 INSERT INTO subscriber_chat_reporting_daily(day,channel,joined,left_count) SELECT strftime('%Y-%m-%d','now'),COALESCE(OLD.chat_kind,OLD.channel),0,1 WHERE OLD.state IN ('pending','active') AND OLD.destination NOT LIKE 'deleted:%' AND OLD.chat_kind IS NOT NULL AND (NEW.state NOT IN ('pending','active') OR NEW.destination LIKE 'deleted:%' OR COALESCE(NEW.chat_kind,NEW.channel) <> COALESCE(OLD.chat_kind,OLD.channel)) ON CONFLICT(day,channel) DO UPDATE SET joined=joined+excluded.joined,left_count=left_count+excluded.left_count;
 INSERT INTO subscriber_chat_reporting_daily(day,channel,joined,left_count) SELECT strftime('%Y-%m-%d','now'),COALESCE(NEW.chat_kind,NEW.channel),1,0 WHERE NEW.state IN ('pending','active') AND NEW.destination NOT LIKE 'deleted:%' AND NEW.chat_kind IS NOT NULL AND (OLD.state NOT IN ('pending','active') OR OLD.destination LIKE 'deleted:%' OR COALESCE(OLD.chat_kind,OLD.channel) <> COALESCE(NEW.chat_kind,NEW.channel)) ON CONFLICT(day,channel) DO UPDATE SET joined=joined+excluded.joined,left_count=left_count+excluded.left_count;
END;

CREATE TRIGGER sms_reporting_insert AFTER INSERT ON subscribers WHEN NEW.sms_kind=1 AND NEW.state IN ('pending','active') AND NEW.destination NOT LIKE 'deleted:%' BEGIN
 INSERT INTO sms_reporting_daily(day,joined,left_count) VALUES(strftime('%Y-%m-%d','now'),1,0) ON CONFLICT(day) DO UPDATE SET joined=joined+1;
END;
CREATE TRIGGER sms_reporting_delete AFTER DELETE ON subscribers WHEN OLD.sms_kind=1 AND OLD.state IN ('pending','active') AND OLD.destination NOT LIKE 'deleted:%' BEGIN
 INSERT INTO sms_reporting_daily(day,joined,left_count) VALUES(strftime('%Y-%m-%d','now'),0,1) ON CONFLICT(day) DO UPDATE SET left_count=left_count+1;
END;
CREATE TRIGGER sms_reporting_update AFTER UPDATE OF state,destination ON subscribers WHEN NEW.sms_kind=1 BEGIN
 INSERT INTO sms_reporting_daily(day,joined,left_count) SELECT strftime('%Y-%m-%d','now'),1,0
 WHERE NEW.state IN ('pending','active') AND NEW.destination NOT LIKE 'deleted:%' AND (OLD.state NOT IN ('pending','active') OR OLD.destination LIKE 'deleted:%') ON CONFLICT(day) DO UPDATE SET joined=joined+1;
 INSERT INTO sms_reporting_daily(day,joined,left_count) SELECT strftime('%Y-%m-%d','now'),0,1
 WHERE OLD.state IN ('pending','active') AND OLD.destination NOT LIKE 'deleted:%' AND (NEW.state NOT IN ('pending','active') OR NEW.destination LIKE 'deleted:%') ON CONFLICT(day) DO UPDATE SET left_count=left_count+1;
END;

-- A separate lifetime shares native subscriber authority without changing any
-- applied table or destination uniqueness. Only the read projection exposes the
-- address held by an incident subscription.
CREATE TABLE incident_follow_settings (
 id INTEGER PRIMARY KEY CHECK(id=1),
 include_report INTEGER NOT NULL DEFAULT 1 CHECK(include_report IN (0,1))
);
INSERT INTO incident_follow_settings(id) VALUES(1);
CREATE TABLE incident_subscriptions (
 subscriber_id TEXT PRIMARY KEY NOT NULL REFERENCES subscribers(id) ON DELETE CASCADE,
 incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE RESTRICT,
 destination TEXT NOT NULL,
 include_report INTEGER NOT NULL DEFAULT 1 CHECK(include_report IN (0,1)),
 resolution_at TEXT,
 resolution_delivered_at TEXT,
 ended_at TEXT,
 final_event_id TEXT,
 created_at TEXT NOT NULL
);
CREATE INDEX incident_subscriptions_incident ON incident_subscriptions(incident_id,ended_at);
CREATE INDEX incident_subscriptions_ending ON incident_subscriptions(ended_at,resolution_delivered_at);
DROP VIEW subscriber_directory;
CREATE VIEW subscriber_directory AS SELECT s.id, CASE WHEN s.sms_kind=1 THEN 'sms' ELSE COALESCE(s.chat_kind,s.channel) END AS channel,
 CASE WHEN s.destination LIKE 'deleted:%' THEN s.destination ELSE COALESCE(f.destination,s.destination) END AS destination,
 s.contact_email,s.state,s.selection_mode,s.token_hash,s.deactivation_reason,s.deactivated_at,
 s.created_at,s.updated_at,s.created_by_operator_id,s.webhook_format,
 CASE WHEN s.preferences_set=0 AND s.channel='email' THEN '["incidents","maintenance"]' ELSE s.event_kinds_json END AS event_kinds_json,
 s.minimum_impact FROM subscribers s LEFT JOIN incident_subscriptions f ON f.subscriber_id=s.id;
CREATE TRIGGER incident_subscriber_erasure AFTER UPDATE OF destination ON subscribers
WHEN NEW.destination LIKE 'deleted:%' BEGIN
 DELETE FROM incident_subscriptions WHERE subscriber_id=NEW.id;
END;

-- Report-only notifications cannot inhabit the original incident/maintenance
-- table's CHECK. Keep that applied table and every old foreign key intact, and
-- add the same carrier/attempt partition used for component notifications.
CREATE TABLE report_notification_deliveries (
 id TEXT PRIMARY KEY NOT NULL,
 subscriber_id TEXT NOT NULL REFERENCES subscribers(id) ON DELETE RESTRICT,
 incident_update_id TEXT REFERENCES incident_updates(id) ON DELETE RESTRICT,
 maintenance_id TEXT REFERENCES maintenance(id) ON DELETE RESTRICT,
 channel TEXT NOT NULL CHECK(channel IN ('email','webhook')),
 outcome TEXT NOT NULL CHECK(outcome IN ('queued','delivered','bounced','complained','suppressed','failed')),
 queued_at TEXT NOT NULL, outcome_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 notification_event_id TEXT NOT NULL,
 notification_event_type TEXT NOT NULL CHECK(notification_event_type='incident-report'),
 incident_report_id TEXT NOT NULL REFERENCES incident_reports(id) ON DELETE RESTRICT,
 mail_payload_json TEXT, dispatch_locked_at TEXT,
 incident_impact TEXT CHECK(incident_impact IN ('none','minor','major','critical')),
 component_event_id TEXT,
 CHECK(incident_update_id IS NULL AND maintenance_id IS NULL AND component_event_id IS NULL),
 CHECK(notification_event_id=incident_report_id)
);
CREATE INDEX report_deliveries_subscriber ON report_notification_deliveries(subscriber_id,queued_at DESC);
CREATE INDEX report_deliveries_dispatch ON report_notification_deliveries(outcome,dispatch_locked_at);
CREATE UNIQUE INDEX report_deliveries_one_event ON report_notification_deliveries(subscriber_id,notification_event_id,channel);
CREATE TABLE report_delivery_attempts (
 id TEXT PRIMARY KEY NOT NULL,
 delivery_id TEXT NOT NULL REFERENCES report_notification_deliveries(id) ON DELETE CASCADE,
 attempt_number INTEGER NOT NULL, attempted_at TEXT NOT NULL, provider_message_id TEXT,
 error TEXT, created_at TEXT NOT NULL, local_capture_id TEXT
 CHECK(local_capture_id IS NULL OR (length(local_capture_id)>0 AND provider_message_id IS NULL AND error IS NULL)),
 UNIQUE(delivery_id,attempt_number)
);
CREATE INDEX report_delivery_attempts_delivery ON report_delivery_attempts(delivery_id,attempted_at);
ALTER TABLE mail_provider_webhook_events ADD COLUMN report_delivery_id TEXT REFERENCES report_notification_deliveries(id) ON DELETE SET NULL;
CREATE TRIGGER report_deliveries_capture_impact AFTER INSERT ON report_notification_deliveries BEGIN
 UPDATE report_notification_deliveries SET incident_impact=(
  SELECT COALESCE(i.impact_override,CASE i.peak_impact WHEN 'Major outage' THEN 'critical'
   WHEN 'Partially unavailable' THEN 'major' WHEN 'Degraded performance' THEN 'minor' ELSE 'none' END)
  FROM incidents i JOIN incident_reports r ON r.incident_id=i.id WHERE r.id=NEW.incident_report_id
 ) WHERE id=NEW.id AND incident_impact IS NULL;
END;

DROP VIEW notification_delivery_records;
DROP VIEW notification_attempt_records;
CREATE VIEW notification_delivery_records AS SELECT d.*,NULL AS component_event_id FROM notification_deliveries d
 UNION ALL SELECT * FROM component_notification_deliveries
 UNION ALL SELECT * FROM report_notification_deliveries;
CREATE VIEW notification_attempt_records AS SELECT * FROM notification_delivery_attempts
 UNION ALL SELECT * FROM component_delivery_attempts
 UNION ALL SELECT * FROM report_delivery_attempts;
CREATE TRIGGER notification_delivery_records_freeze
INSTEAD OF UPDATE OF mail_payload_json ON notification_delivery_records
WHEN OLD.mail_payload_json IS NULL BEGIN
 UPDATE notification_deliveries SET mail_payload_json=NEW.mail_payload_json WHERE id=OLD.id AND mail_payload_json IS NULL;
 UPDATE component_notification_deliveries SET mail_payload_json=NEW.mail_payload_json WHERE id=OLD.id AND mail_payload_json IS NULL;
 UPDATE report_notification_deliveries SET mail_payload_json=NEW.mail_payload_json WHERE id=OLD.id AND mail_payload_json IS NULL;
END;
CREATE TRIGGER notification_attempt_records_insert
INSTEAD OF INSERT ON notification_attempt_records BEGIN
 SELECT RAISE(ABORT,'Unknown delivery.') WHERE NOT EXISTS(SELECT 1 FROM notification_delivery_records WHERE id=NEW.delivery_id);
 INSERT INTO notification_delivery_attempts(id,delivery_id,attempt_number,attempted_at,provider_message_id,error,created_at,local_capture_id)
 SELECT NEW.id,NEW.delivery_id,NEW.attempt_number,NEW.attempted_at,NEW.provider_message_id,NEW.error,NEW.created_at,NEW.local_capture_id
 WHERE EXISTS(SELECT 1 FROM notification_deliveries WHERE id=NEW.delivery_id) ON CONFLICT DO NOTHING;
 INSERT INTO component_delivery_attempts(id,delivery_id,attempt_number,attempted_at,provider_message_id,error,created_at,local_capture_id)
 SELECT NEW.id,NEW.delivery_id,NEW.attempt_number,NEW.attempted_at,NEW.provider_message_id,NEW.error,NEW.created_at,NEW.local_capture_id
 WHERE EXISTS(SELECT 1 FROM component_notification_deliveries WHERE id=NEW.delivery_id) ON CONFLICT DO NOTHING;
 INSERT INTO report_delivery_attempts(id,delivery_id,attempt_number,attempted_at,provider_message_id,error,created_at,local_capture_id)
 SELECT NEW.id,NEW.delivery_id,NEW.attempt_number,NEW.attempted_at,NEW.provider_message_id,NEW.error,NEW.created_at,NEW.local_capture_id
 WHERE EXISTS(SELECT 1 FROM report_notification_deliveries WHERE id=NEW.delivery_id) ON CONFLICT DO NOTHING;
END;
